   370  /*
   371   * turn a coolkey object into a pkcss 15 pubkey. object should already be type
   372   * CKO_PUBLIC_KEY */
   373  static sc_pkcs15_pubkey_t *
   374  coolkey_make_public_key(sc_card_t *card, sc_cardctl_coolkey_object_t *obj, CK_KEY_TYPE key_type)
   375  {
   376          sc_pkcs15_pubkey_t *key;
   377          int r;
   378
   379          key = calloc(1, sizeof(struct sc_pkcs15_pubkey));
   380          if (!key)
   381                  return NULL;
   382          switch (key_type) {
   383          case CKK_RSA:
   384                  key->algorithm = SC_ALGORITHM_RSA;
   385                  r = coolkey_get_attribute_lv(card, obj, CKA_MODULUS, &key->u.rsa.modulus);
   386                  if (r != SC_SUCCESS) {
   387                          goto fail;
   388                  }
   389                  r = coolkey_get_attribute_lv(card, obj, CKA_PUBLIC_EXPONENT, &key->u.rsa.exponent);
   390                  if (r != SC_SUCCESS) {
   391                          goto fail;
   392                  }
   393                  break;
   394          case CKK_EC:
   395                  key->algorithm = SC_ALGORITHM_EC;
   396                  r = coolkey_get_attribute_bytes_alloc(card, obj, CKA_EC_POINT, &key->u.ec.ecpointQ.value, &key->u.ec.ecpointQ.len);
   397              if(r < 0) {
   398                          goto fail;
   399                  }
   400                  r = coolkey_get_attribute_bytes_alloc(card, obj, CKA_EC_PARAMS,
   401                                  &key->u.ec.params.der.value, &key->u.ec.params.der.len);
   402                  if (r < 0) {
   403                          goto fail;
   404                  }
   405                  r = sc_pkcs15_fix_ec_parameters(card->ctx, &key->u.ec.params);
   406                  if (r < 0) {
   407                          goto fail;
   408                  }
   409                  break;
   410          }
   411          return key;
   412  fail:
   413          sc_pkcs15_free_pubkey(key);
   414
   415          /* now parse the DER cert */
   416          return NULL;
   417  }
