   420  static sc_pkcs15_pubkey_t *
   421  coolkey_get_public_key_from_certificate(sc_pkcs15_card_t *p15card, sc_cardctl_coolkey_object_t *obj)
   422  {
   423          sc_pkcs15_cert_info_t cert_info;
   424          sc_pkcs15_cert_t *cert_out = NULL;
   425          sc_pkcs15_pubkey_t *key = NULL;
   426          int r;
   427
   428          cert_info.value.value = NULL;
   429          r = coolkey_get_certificate(p15card->card, obj, &cert_info.value);
   430          if (r < 0) {
   431                  goto fail;
   432          }
   433          r = sc_pkcs15_read_certificate(p15card, &cert_info, &cert_out);
   434          if (r < 0) {
   435                  goto fail;
   436          }
   437          key = cert_out->key;
   438          cert_out->key = NULL; /* adopt the key from the cert */
   439  fail:
   440          if (cert_out) {
   441                  sc_pkcs15_free_certificate(cert_out);
   442          }
   443          if (cert_info.value.value) {
   444                  free(cert_info.value.value);
   445          }
   446          return key;
   447  }
