   449  static sc_pkcs15_pubkey_t *
   450  coolkey_get_public_key(sc_pkcs15_card_t *p15card, sc_cardctl_coolkey_object_t *obj, CK_KEY_TYPE key_type)
   451  {
   452          sc_pkcs15_pubkey_t *key;
   453
   454          key = coolkey_make_public_key(p15card->card, obj, key_type);
   455          if (key) {
   456                  return key;
   457          }
   458          return coolkey_get_public_key_from_certificate(p15card, obj);
   459  }
